38	@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
39	@Testcontainers
40	class CommunityIntegrationTest {
41	
42	    @Container
43	    static MySQLContainer<?> mysql = new MySQLContainer<>("mysql:8.4").withDatabaseName("community");
44	
45	    @Container
46	    static KafkaContainer kafka =
47	            new KafkaContainer(DockerImageName.parse("confluentinc/cp-kafka:7.6.1"));
48	
49	    private final ObjectMapper objectMapper = new ObjectMapper();
50	
51	    @DynamicPropertySource
52	    static void props(DynamicPropertyRegistry r) {
53	        r.add("spring.datasource.url", mysql::getJdbcUrl);
54	        r.add("spring.datasource.username", mysql::getUsername);
55	        r.add("spring.datasource.password", mysql::getPassword);
56	        r.add("spring.kafka.bootstrap-servers", kafka::getBootstrapServers);
57	    }
58	
59	    @LocalServerPort
60	    int port;
61	
62	    @BeforeEach
63	    void setUp() {
64	        RestAssured.port = port;
65	    }
66	
67	    private KafkaConsumer<String, String> newConsumer(String topic) {
68	        Properties props = new Properties();
69	        props.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, kafka.getBootstrapServers());
70	        props.put(ConsumerConfig.GROUP_ID_CONFIG, "test-" + topic + "-" + System.nanoTime());
71	        props.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, "earliest");
72	        props.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
73	        props.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
74	        KafkaConsumer<String, String> consumer = new KafkaConsumer<String, String>(props);
75	        consumer.subscribe(Collections.singletonList(topic));
76	        return consumer;
77	    }
78	
79	    private Map<String, Object> pollOne(KafkaConsumer<String, String> consumer) throws Exception {
80	        long deadline = System.currentTimeMillis() + 20000L;
81	        while (System.currentTimeMillis() < deadline) {
82	            ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(500));
83	            for (ConsumerRecord<String, String> record : records) {
84	                @SuppressWarnings("unchecked")
85	                Map<String, Object> parsed = objectMapper.readValue(record.value(), HashMap.class);
86	                return parsed;
87	            }
88	        }
89	        return null;
90	    }
91	
92	    @Test
93	    void createPostReturns201AndPublishesPostCreatedAndMoodLogged() throws Exception {
94	        KafkaConsumer<String, String> postConsumer = newConsumer("post.created");
95	        KafkaConsumer<String, String> moodConsumer = newConsumer("mood.logged");
96	        try {
97	            String postId = given().contentType(ContentType.JSON)
98	                    .body("{\"userId\":\"user-1\",\"title\":\"t\",\"category\":\"career\","
99	                            + "\"content\":\"c\",\"moodEmoji\":\"😔\",\"nickname\":\"nick\"}")
100	                    .when().post("/internal/posts")
101	                    .then().statusCode(201)
102	                    .body("postId", not(emptyOrNullString()))
103	                    .extract().path("postId");
104	
105	            Map<String, Object> postEvent = pollOne(postConsumer);
106	            assertNotNull(postEvent, "post.created 메시지가 발행되어야 한다");
